-- Real SQLite: ask the plan, then read SCAN vs SEARCH
EXPLAIN QUERY PLAN
SELECT name FROM developers WHERE country = 'Japan';
-- Without index: SCAN developers  (~every row read)

CREATE INDEX idx_developers_country ON developers(country);

EXPLAIN QUERY PLAN
SELECT name FROM developers WHERE country = 'Japan';
-- With index: SEARCH developers USING INDEX idx_developers_country

-- Real SQLite/PostgreSQL: the full index lifecycle
CREATE INDEX idx_enrollments_course ON enrollments(course_id);
CREATE INDEX idx_enrollments_dev ON enrollments(developer_id);
CREATE UNIQUE INDEX idx_developers_email ON developers(email);

-- Inspect what exists, remove what earns nothing
-- SQLite:  SELECT name, tbl_name FROM sqlite_master WHERE type = 'index';
-- Postgres: SELECT indexname FROM pg_indexes WHERE tablename = 'enrollments';
DROP INDEX IF EXISTS idx_enrollments_dev;

