-- (a) sandbox selectivity probe (flat — runs here)
-- SELECT * FROM enrollments WHERE course_id = 5;
-- A few rows of 28: selective → index candidate.

-- (b) real SQLite plan + fix
EXPLAIN QUERY PLAN
SELECT d.name, e.progress FROM enrollments e
JOIN developers d ON d.id = e.developer_id
WHERE e.course_id = 5 ORDER BY e.progress DESC;

CREATE INDEX idx_enrollments_course ON enrollments(course_id);
-- developers(id) needs nothing: PRIMARY KEYs are indexed automatically.
-- Expected: SCAN enrollments → SEARCH enrollments USING INDEX idx_enrollments_course;
-- join stays a key lookup; re-run EXPLAIN to confirm, and only then
-- consider (course_id, progress) if ORDER BY still sorts.

